'use strict';

function normalizeZero(value) {
  return Object.is(value, -0) ? 0 : value;
}

function summarizeSensors(readings) {
  if (!Array.isArray(readings)) {
    throw new TypeError('readings must be an array');
  }

  const totals = new Map();
  for (const reading of readings) {
    if (reading === null || typeof reading !== 'object' || Array.isArray(reading) ||
        typeof reading.zone !== 'string' || reading.zone.length === 0 ||
        typeof reading.value !== 'number' || !Number.isFinite(reading.value)) {
      throw new TypeError('invalid reading');
    }
    const value = normalizeZero(reading.value);
    const current = totals.get(reading.zone);
    if (current) {
      current.count += 1;
      current.sum += value;
      current.minimum = Math.min(current.minimum, value);
      current.maximum = Math.max(current.maximum, value);
    } else {
      totals.set(reading.zone, {
        count: 1,
        sum: value,
        minimum: value,
        maximum: value
      });
    }
  }

  const result = {};
  for (const [zone, data] of totals) {
    Object.defineProperty(result, zone, {
      value: {
        count: data.count,
        minimum: normalizeZero(data.minimum),
        maximum: normalizeZero(data.maximum),
        average: normalizeZero(data.sum / readings.length)
      },
      enumerable: true,
      configurable: true,
      writable: true
    });
  }
  return result;
}

module.exports = { summarizeSensors };

