'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['summarizeSensors']);
assert.strictEqual(typeof api.summarizeSensors, 'function');

const empty = api.summarizeSensors([]);
assert.strictEqual(typeof empty, 'object');
assert.notStrictEqual(empty, null);
assert.strictEqual(Array.isArray(empty), false);
assert.deepStrictEqual(Object.keys(empty), []);

const readings = Object.freeze([
  Object.freeze({ zone: 'north', value: 3 }),
  Object.freeze({ zone: 'south', value: 10 }),
  Object.freeze({ zone: 'north', value: 7 }),
  Object.freeze({ zone: 'east', value: -0 }),
  Object.freeze({ zone: 'south', value: -2 })
]);
const summary = api.summarizeSensors(readings);
assert.deepStrictEqual(Object.keys(summary), ['north', 'south', 'east']);
assert.deepStrictEqual(summary.north, { count: 2, minimum: 3, maximum: 7, average: 5 });
assert.deepStrictEqual(summary.south, { count: 2, minimum: -2, maximum: 10, average: 4 });
assert.deepStrictEqual(summary.east, { count: 1, minimum: 0, maximum: 0, average: 0 });
for (const field of ['minimum', 'maximum', 'average']) {
  assert.strictEqual(Object.is(summary.east[field], -0), false);
}

summary.north.count = 100;
const again = api.summarizeSensors(readings);
assert.deepStrictEqual(again.north, { count: 2, minimum: 3, maximum: 7, average: 5 });
assert.notStrictEqual(again, summary);
assert.notStrictEqual(again.north, summary.north);

const special = api.summarizeSensors([{ zone: '__proto__', value: 4 }]);
assert.strictEqual(Object.prototype.hasOwnProperty.call(special, '__proto__'), true);
assert.deepStrictEqual(special['__proto__'], { count: 1, minimum: 4, maximum: 4, average: 4 });

for (const invalid of [
  null, undefined, {}, 'readings',
  [null], [[]], [{}],
  [{ zone: '', value: 1 }],
  [{ zone: 2, value: 1 }],
  [{ zone: 'x', value: '1' }],
  [{ zone: 'x', value: NaN }],
  [{ zone: 'x', value: Infinity }],
  [{ zone: 'x', value: -Infinity }]
]) {
  assert.throws(() => api.summarizeSensors(invalid), TypeError);
}

